window.products.push({"id":1189274,"name":"2CA1700 - Intel RS2BL040 4-Ports SAS RAID Controller - Serial Attached SCSI - PCI Express x8 - Plug-in Card","category":"electronics","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/418BeaNtN-L._AC_.jpg","description":"Description: The Intel RAID Controller RS2BL040, a member of Intel's 6Gb/s SAS adapter family, is targeted at solutions with expander backplanes or low drive counts. Features including LSI's SAS2108 6Gb/s RAID on Chip (ROC) silicon and a native PCI Express 2.0 architecture allow for significant performance gains for both 3Gb/s and 6Gb/s drive-based solutions versus prior generation RAID adapters. Data protection and availability are enhanced by new features including Decision Feedback Equalization for greater signal integrity, enhanced diagnostics, and more robust error reporting.","images":["https://m.media-amazon.com/images/I/418BeaNtN-L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Intel","source_asin":"B002NWWIFS","category_path":"Electronics"},"sku":"BM-1189274","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B002NWWIFS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B002NWWIFS","price_pending":true,"merchant_ready":false});
